SELECT DISTINCT p.property_type_code, rpt.property_type_description
FROM Properties p
JOIN Ref_Property_Types rpt ON p.property_type_code = rpt.property_type_code;

SELECT p.property_name
FROM Properties p
WHERE (p.property_type_code = 'HSE' OR p.property_type_code = 'APT') AND p.room_count > 1;

SELECT SUM(Population) AS TotalPopulation, AVG(SurfaceArea) AS AverageArea 
FROM country 
WHERE Continent = 'North America' AND SurfaceArea > 3000;
